practice.solution:
from fractions import Fraction
from sympy import sqrt

def signs(quadrant):
    if quadrant == 1:
        return 1, 1
    elif quadrant == 2:
        return -1, 1
    elif quadrant == 3:
        return -1, -1
    else:
        return 1, -1

def solve(given, value, quadrant):
    cs, ss = signs(quadrant)
    if given == "cos":
        return ss * sqrt(1 - value**2), value
    elif given == "sin":
        return value, cs * sqrt(1 - value**2)
    else:
        c = 1 / (cs * sqrt(1 + value**2))
        return value * c, c

n = int(input())
for i in range(n):
    given = input()
    value = Fraction(int(input()), int(input()))
    quadrant = int(input())
    s, c = solve(given, value, quadrant)
    print(f"{given} = {value}, quadrant {quadrant}: sin = {s}, cos = {c}, tan = {s / c}")
    print(f"  sec = {1 / c}, csc = {1 / s}, cot = {c / s}")

