import math

def value(name, degrees):
    t = math.radians(degrees)
    if name == "sin":
        return math.sin(t)
    elif name == "cos":
        return math.cos(t)
    elif name == "tan":
        return math.tan(t)
    elif name == "csc":
        return 1 / math.sin(t)
    elif name == "sec":
        return 1 / math.cos(t)
    else:
        return 1 / math.tan(t)

def rewrite(name, form):
    if form == "-t":
        if name == "cos" or name == "sec":
            return 1, name
        return -1, name
    partner = {"sin": "cos", "cos": "sin", "tan": "cot", "cot": "tan", "sec": "csc", "csc": "sec"}
    return 1, partner[name]

def show(label, name, form, t):
    sign, new = rewrite(name, form)
    if sign == 1:
        right = f"{new}(t)"
    else:
        right = f"-{new}(t)"
    print(f"{label}: {name}({form}) = {right}")
    if form == "-t":
        left = value(name, -t)
    else:
        left = value(name, 90 - t)
    print(f"  check at t = {t}: {left:.6f} and {sign * value(new, t):.6f}")

show("Example 2", "sin", "-t", 30)
show("Example 2", "cos", "-t", 60)
show("Example 3", "sec", "-t", 60)
show("Example 3", "csc", "-t", 30)
show("Example 4", "sin", "90-t", 60)
show("Example 4", "cot", "90-t", 25)

