from sympy import sympify, simplify

n = int(input())
for i in range(n):
    m = int(input())
    lines = []
    for j in range(m):
        lines.append(input())
    exprs = []
    for line in lines:
        exprs.append(sympify(line))
    print(f"proof {i + 1}: {lines[0]}  ->  {lines[m - 1]}")
    valid = True
    for k in range(m - 1):
        if simplify(exprs[k] - exprs[k + 1]) == 0:
            print(f"  step {k + 1}: ok")
        else:
            print(f"  step {k + 1}: not equal")
            valid = False
    if valid:
        print("  valid proof")
    else:
        print("  broken proof")
